package frontmatter

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// ErrNoDate is returned when a page's front matter has no date field.
var ErrNoDate = errors.New("front matter has no date")

// dateLayouts are the accepted forms of the `date:` field, most specific first.
var dateLayouts = []string{
	time.RFC3339,
	"2006-01-02T15:04:05",
	"2006-01-02",
}

// parseFrontMatterDate turns the raw `date:` value of a page's front matter into a timestamp.
// file is the page's path, used only in the error message.
func parseFrontMatterDate(file, raw string) (time.Time, error) {
	value := strings.Trim(strings.TrimSpace(raw), `"'`)
	if value == "" {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	for _, layout := range dateLayouts {
		parsed, err := time.Parse(layout, value)
		if err == nil {
			return parsed.UTC(), nil
		}
	}

	return time.Time{}, fmt.Errorf("invalid date in %s: %q", file, value)
}

// PageDate reads the date field from parsed front matter.
func PageDate(file string, fields map[string]string) (time.Time, error) {
	raw, ok := fields["date"]
	if !ok {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	return parseFrontMatterDate(file, raw)
}

package slug

import (
	"strings"
	"unicode"

	"golang.org/x/text/runes"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// foldAccents strips combining marks after NFD decomposition, so "é" becomes "e".
var foldAccents = transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)

// Slugify builds a page's URL slug from its title: lowercase, ASCII-folded, with every run of
// non-alphanumeric characters collapsed to one hyphen and hyphens trimmed from both ends.
func Slugify(title string) string {
	folded, _, err := transform.String(foldAccents, title)
	if err != nil {
		folded = title
	}

	var out strings.Builder
	pendingHyphen := false

	for _, r := range strings.ToLower(folded) {
		if r < unicode.MaxASCII && (unicode.IsLetter(r) || unicode.IsDigit(r)) {
			if pendingHyphen && out.Len() > 0 {
				out.WriteByte('-')
			}
			out.WriteRune(r)
			pendingHyphen = false
			continue
		}
		pendingHyphen = true
	}

	return out.String()
}

package render

import (
	"html/template"
	"os"
	"sync"
	"time"
)

type cacheEntry struct {
	tmpl    *template.Template
	modTime time.Time
}

// TemplateCache holds compiled templates by path and recompiles one when its file changes.
type TemplateCache struct {
	mu      sync.Mutex
	entries map[string]cacheEntry
	stat    func(string) (os.FileInfo, error)
	compile func(string) (*template.Template, error)
}

// NewTemplateCache returns an empty cache that reads templates from disk.
func NewTemplateCache() *TemplateCache {
	return &TemplateCache{
		entries: map[string]cacheEntry{},
		stat:    os.Stat,
		compile: func(path string) (*template.Template, error) { return template.ParseFiles(path) },
	}
}

// Get returns the compiled template for path, dropping and recompiling the cached entry when the
// file's modification time differs from the one it was compiled at.
func (c *TemplateCache) Get(path string) (*template.Template, error) {
	info, err := c.stat(path)
	if err != nil {
		return nil, err
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	if entry, ok := c.entries[path]; ok && entry.modTime.Equal(info.ModTime()) {
		return entry.tmpl, nil
	}

	delete(c.entries, path)

	tmpl, err := c.compile(path)
	if err != nil {
		return nil, err
	}

	c.entries[path] = cacheEntry{tmpl: tmpl, modTime: info.ModTime()}

	return tmpl, nil
}
